package vn.contractgovernance.api.control;

import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.stereotype.Service;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.node.ObjectNode;
import vn.contractgovernance.api.shared.*;
import vn.contractgovernance.api.contract.*;
import vn.contractgovernance.api.customer.CustomerAccess;
import vn.contractgovernance.api.identity.UserDirectory;
import vn.contractgovernance.api.incident.IncidentService;
import vn.contractgovernance.api.signing.SigningEvidence;
import vn.contractgovernance.api.change.ChangeService;
import vn.contractgovernance.api.notice.NoticeService;
import static vn.contractgovernance.api.change.ChangeService.id;

@Service
public class ControlService {
 public record Frozen(UUID id,JsonNode revision,JsonNode metadata,String hash){}
 private final EntityStore store;private final JsonSupport json;private final Clock clock;private final CalendarService calendar;private final UserDirectory users;private final ContractLifecycle lifecycle;private final CustomerAccess customers;private final ControlEvidence evidence;private final SigningEvidence signing;private final IncidentService incidents;private final ChangeService changes;private final NoticeService notices;private final CommandExecutor commands;private final ContractRegistry schemas;private final AuditService audit;private final ListQueries lists;private final ObjectProvider<ControlApproval> approval;
 public ControlService(EntityStore store,JsonSupport json,Clock clock,CalendarService calendar,UserDirectory users,ContractLifecycle lifecycle,CustomerAccess customers,ControlEvidence evidence,SigningEvidence signing,IncidentService incidents,ChangeService changes,NoticeService notices,CommandExecutor commands,ContractRegistry schemas,AuditService audit,ListQueries lists,ObjectProvider<ControlApproval> approval){this.store=store;this.json=json;this.clock=clock;this.calendar=calendar;this.users=users;this.lifecycle=lifecycle;this.customers=customers;this.evidence=evidence;this.signing=signing;this.incidents=incidents;this.changes=changes;this.notices=notices;this.commands=commands;this.schemas=schemas;this.audit=audit;this.lists=lists;this.approval=approval;}
 public String now(){return JsonSupport.timestamp(clock.instant());}
 public EntityStore.Entity require(UUID id,Actor actor){var r=store.require("ControlRequest",id);var current=users.actor(actor.id());current.requireBranch(r.branchId());lifecycle.require(id(r.body(),"contractId"),current);return r;}
 public EntityStore.Entity lock(UUID id){var r=store.require("ControlRequest",id);lifecycle.lock(id(r.body(),"contractId"));return store.lock("ControlRequest",id);}
 public void maker(EntityStore.Entity r,Actor actor){customers.requireAssignedMaker(id(store.require("Contract",id(r.body(),"contractId")).body(),"relationshipId"),users.actor(actor.id()));}
 public Set<UUID> contributors(EntityStore.Entity r){var ids=new TreeSet<>(evidence.ids(r.body().path("contributorIds")));if(r.body().hasNonNull("requesterId"))ids.add(id(r.body(),"requesterId"));ids.addAll(evidence.uploaders(evidence.ids(r.body().path("evidenceFileIds"))));store.jdbc().query("select body->>'uploadedBy' from cg_entity where entity_type='File' and body->>'targetKind'='CONTROL_REQUEST' and body->>'targetId'=? and body->>'uploadedBy' is not null",(rs,n)->UUID.fromString(rs.getString(1)),r.id().toString()).forEach(ids::add);return ids;}
 public void independent(EntityStore.Entity r,Actor actor){users.actor(actor.id()).requireRole("CHECKER");require(r.id(),actor);if(contributors(r).contains(actor.id()))throw ApiException.of("SOD_VIOLATION","Control cần checker độc lập nguồn.");}
 public EntityStore.Entity save(EntityStore.Entity r,ObjectNode b,Actor actor,String action,String reason){b.put("updatedAt",now());var next=store.update(r,b);schemas.validateSchema("ControlRequest",next.body());audit.record(actor,action,next,reason);return next;}
 public void state(EntityStore.Entity r,String... states){if(!Set.of(states).contains(r.body().path("state").asString()))throw ApiException.of("STATE_CONFLICT","Control state không phù hợp.");}
 public void sourceGuard(EntityStore.Entity r){var c=store.require("Contract",id(r.body(),"contractId"));String kind=r.body().path("kind").asString(),s=c.body().path("serviceState").asString(),status=c.body().path("state").asString();switch(kind){
  case "ACTIVATE"->{active(c);ready(c);if(!s.equals("NOT_STARTED"))throw ApiException.of("STATE_CONFLICT","Dịch vụ không NOT_STARTED.");}
  case "RESUME"->{active(c);ready(c);if(!s.equals("SUSPENDED"))throw ApiException.of("STATE_CONFLICT","Dịch vụ không SUSPENDED.");try{incidents.requireResumeAllowed(c.id());}catch(ApiException blocked){if(blocked.code().equals("READINESS_BLOCKED"))throw ApiException.of("UNRESOLVED_DUTY",blocked.getMessage());throw blocked;}}
  case "SUSPEND"->{active(c);if(!s.equals("RUNNING"))throw ApiException.of("STATE_CONFLICT","Dịch vụ không RUNNING.");}
  case "TERMINATE"->{active(c);}
  case "STOP"->{if(!Set.of("EXPIRED","TERMINATED").contains(status)||!Set.of("NOT_STARTED","RUNNING","SUSPENDED").contains(s))throw ApiException.of("STATE_CONFLICT","STOP chỉ cho hợp đồng kết thúc và dịch vụ còn chạy/tạm dừng.");}
  default->throw ApiException.validation("/kind","Loại control không hợp lệ.");
 }}
 private void active(EntityStore.Entity c){if(!c.body().path("state").asString().equals("ACTIVE"))throw ApiException.of("STATE_CONFLICT","Hợp đồng không ACTIVE.");}
 private void ready(EntityStore.Entity c){if(!c.body().path("readiness").asString().equals("READY")||ContractLifecycle.unresolvedRisk(c.body()))throw ApiException.of("READINESS_BLOCKED","Readiness có blocker.");signing.requireMaterial(c);}
 private void author(EntityStore.Entity r,Actor actor){var current=users.actor(actor.id());if(r.body().path("kind").asString().equals("SUSPEND")&&r.body().path("urgent").asBoolean()&&current.hasRole("CHECKER")&&r.body().path("requesterId").asString().equals(actor.id().toString())){require(r.id(),actor);return;}maker(r,actor);}
 public ApiResult create(JsonNode request,String key,Actor actor){UUID cid=id(request,"contractId");lifecycle.require(cid,actor);creationRole(request,actor);return commands.execute(actor,key,"POST","/api/v1/control-requests",request,null,()->{lifecycle.require(cid,actor);creationRole(request,actor);},()->lifecycle.maintain(cid,actor),()->{var c=lifecycle.lock(cid);creationRole(request,actor);var b=(ObjectNode)json.nfc(request);b.put("createdAt",now()).put("updatedAt",now()).put("branchId",c.branchId().toString()).put("state","DRAFT").put("requesterId",actor.id().toString());for(String f:List.of("roundId","externalAcknowledgement","observedAt"))b.putNull(f);var ids=evidence.ids(b.path("evidenceFileIds"));var cs=evidence.uploaders(ids);cs.add(actor.id());if(cs.size()>50)throw ApiException.validation("/contributorIds","Quá 50 contributors.");b.set("contributorIds",json.value(cs.stream().map(UUID::toString).toList()));b.set("allowedActions",json.array());b.set("blockedActions",json.array());var r=new EntityStore.Entity("ControlRequest",UUID.randomUUID(),c.branchId(),1,b);sourceGuard(r);if(store.jdbc().queryForObject("select count(*) from cg_entity where entity_type='ControlRequest' and body->>'contractId'=? and body->>'kind'=? and body->>'state' not in ('CONFIRMED','REJECTED','CANCELLED')",Long.class,cid.toString(),b.path("kind").asString())!=0L)throw ApiException.of("STATE_CONFLICT","Đã có Control cùng loại chưa kết thúc.");r=store.create("ControlRequest",r.id(),c.branchId(),b);evidence.manifest(r,ids,actor,true);schemas.validateSchema("ControlRequest",r.body());audit.record(actor,"CREATE",r,request.path("reason").asString());return ApiResult.created(project(r,actor),"/api/v1/control-requests/"+r.id());});}
 private void creationRole(JsonNode request,Actor actor){var current=users.actor(actor.id());if(request.path("kind").asString().equals("SUSPEND")&&request.path("urgent").asBoolean()&&current.hasRole("CHECKER"))return;customers.authorizeAssignedMaker(id(store.require("Contract",id(request,"contractId")).body(),"relationshipId"),current);}
 public Frozen freeze(EntityStore.Entity r,Actor actor){var revision=json.object().put("id",UUID.randomUUID().toString()).put("submittedAt",now());for(String f:List.of("contractId","kind","effectOn","reason","evidenceFileIds","noticeId","urgent","requesterId"))revision.set(f,r.body().path(f));var cs=contributors(r);if(cs.size()>50)throw ApiException.validation("/contributorIds","Quá 50 contributors.");revision.set("contributorIds",json.value(cs.stream().map(UUID::toString).toList()));schemas.validateSchema("ControlRevision",revision);var c=store.require("Contract",id(r.body(),"contractId"));var metadata=json.object();metadata.set("contractVersion",c.body().path("currentVersion"));metadata.set("evidence",evidence.manifest(r,evidence.ids(r.body().path("evidenceFileIds")),actor,true));metadata.set("artifact",evidence.manifest(r,List.of(id(c.body().path("currentVersion"),"artifactId")),actor,true));if(r.body().hasNonNull("noticeId"))metadata.set("notice",notices.controlProof(id(r.body(),"noticeId"),c.id(),actor,r.body().path("kind").asString().equals("TERMINATE")));var all=json.object();all.set("revision",revision);all.set("metadata",metadata);String hash=json.hash(all);store.jdbc().update("insert into cg_control_revision(id,request_id,revision,metadata,source_hash,submitted_by,submitted_at) values(?,?,?::jsonb,?::jsonb,?,?,?)",id(revision,"id"),r.id(),json.stringify(revision),json.stringify(metadata),hash,actor==null?null:actor.id(),Timestamp.from(clock.instant()));return new Frozen(id(revision,"id"),revision,metadata,hash);}
 public Frozen frozen(EntityStore.Entity r){UUID revision;if(r.body().hasNonNull("roundId"))revision=id(store.require("Round",id(r.body(),"roundId")).body(),"revisionId");else revision=store.jdbc().query("select id from cg_control_revision where request_id=? order by submitted_at desc,id desc limit 1",(rs,n)->rs.getObject(1,UUID.class),r.id()).stream().findFirst().orElseThrow(()->ApiException.of("STATE_CONFLICT","Chưa có source chốt."));return revision(revision,r.id());}
 public Frozen revision(UUID revision,UUID request){var f=store.jdbc().query("select revision::text,metadata::text,source_hash from cg_control_revision where id=? and request_id=?",(rs,n)->new Frozen(revision,json.parse(rs.getString(1)),json.parse(rs.getString(2)),rs.getString(3)),revision,request).stream().findFirst().orElseThrow(()->ApiException.of("STORAGE_INTEGRITY","Control source missing."));var all=json.object();all.set("revision",f.revision());all.set("metadata",f.metadata());if(!json.hash(all).equals(f.hash()))throw ApiException.of("STORAGE_INTEGRITY","Control source hash mismatch.");return f;}
 public void current(EntityStore.Entity r,Frozen f,Actor actor){sourceGuard(r);for(String field:List.of("contractId","kind","effectOn","reason","evidenceFileIds","noticeId","urgent","requesterId"))if(!r.body().path(field).equals(f.revision().path(field)))throw ApiException.of("STORAGE_INTEGRITY","Control khác nguồn chốt.");var c=store.require("Contract",id(r.body(),"contractId"));if(!c.body().path("currentVersion").equals(f.metadata().path("contractVersion")))throw ApiException.of("BASE_CONFLICT","Current ContractVersion đã thay đổi.");if(!evidence.manifest(r,evidence.ids(f.revision().path("evidenceFileIds")),actor,false).equals(f.metadata().path("evidence"))||!evidence.manifest(r,List.of(id(c.body().path("currentVersion"),"artifactId")),actor,false).equals(f.metadata().path("artifact")))throw ApiException.of("STORAGE_INTEGRITY","Control evidence changed.");if(r.body().hasNonNull("noticeId")&&!notices.controlProof(id(r.body(),"noticeId"),c.id(),actor,r.body().path("kind").asString().equals("TERMINATE")).equals(f.metadata().path("notice")))throw ApiException.of("BASE_CONFLICT","Notice proof changed.");}
 private void authorize(EntityStore.Entity r,String action,Actor actor){if(action.equals("CONFIRM")){independent(r,actor);return;}if(action.equals("CANCEL")&&(r.body().path("state").asString().equals("APPROVED")||!r.body().hasNonNull("requesterId"))){independent(r,actor);return;}author(r,actor);}
 public ApiResult command(UUID id,JsonNode request,String tag,String key,Actor actor){var r=require(id,actor);String action=request.path("action").asString();authorize(r,action,actor);ETags.require(tag);UUID cid=id(r.body(),"contractId");return commands.execute(actor,key,"POST","/api/v1/control-requests/"+id+"/commands",request,tag,()->authorize(require(id,actor),action,actor),()->lifecycle.maintain(cid,actor),()->{var current=lock(id);authorize(current,action,actor);ETags.check(tag,current.version());if(action.equals("SUBMIT"))return ApiResult.ok(project(approval.getObject().submit(current,request,actor),actor));if(action.equals("CONFIRM"))return ApiResult.ok(project(confirm(current,request,actor),actor));if(!action.equals("CANCEL"))throw ApiException.validation("/action","Unsupported action.");state(current,"DRAFT","REQUESTED","IN_REVIEW","APPROVED");var refs=evidence.ids(request.path("evidenceFileIds"));if((current.body().path("state").asString().equals("APPROVED")||!current.body().hasNonNull("requesterId"))&&refs.isEmpty())throw ApiException.of("READINESS_BLOCKED","Cần chứng cứ hủy/not-applicable độc lập.");evidence.manifest(current,refs,actor,true);var event=(ObjectNode)request.deepCopy();event.set("manifest",evidence.manifest(current,refs,actor,false));event(current,"CANCEL",event,actor);approval.getObject().cancelRound(current,actor);var b=(ObjectNode)current.body().deepCopy();b.put("state","CANCELLED");return ApiResult.ok(project(save(current,b,actor,"CANCEL",request.path("reason").asString()),actor));});}
 private EntityStore.Entity confirm(EntityStore.Entity r,JsonNode request,Actor actor){String kind=r.body().path("kind").asString();state(r,Set.of("SUSPEND","STOP").contains(kind)?"REQUESTED":"APPROVED");if(!r.body().hasNonNull("roundId")&&store.jdbc().queryForObject("select count(*) from cg_control_revision where request_id=?",Long.class,r.id())==0L)freeze(r,null);var f=frozen(r);current(r,f,actor);if(r.body().hasNonNull("roundId"))approval.getObject().requireApproved(r,f,actor);evidence.nonfuture(request.path("observedAt"));evidence.nonfuture(request.path("externalAcknowledgement").path("observedAt"));var refs=evidence.ids(request.path("externalAcknowledgement").path("fileIds"));var excluded=contributors(r);excluded.addAll(evidence.uploaders(refs));if(excluded.contains(actor.id()))throw ApiException.of("SOD_VIOLATION","Confirmer đã contribute nguồn/chứng cứ acknowledgement.");var c=store.require("Contract",id(r.body(),"contractId"));var observed=Instant.parse(request.path("observedAt").asString());var ack=Instant.parse(request.path("externalAcknowledgement").path("observedAt").asString());var start=calendar.startOfDay(LocalDate.parse(c.body().path("currentVersion").path("terms").path("startOn").asString()));if(kind.equals("ACTIVATE")&&ack.isBefore(start))throw ApiException.of("STATE_CONFLICT","Acknowledgement trước agreement start.");if(kind.equals("RESUME")){var last=lastSuspension(c.id());if(ack.isBefore(last))throw ApiException.of("STATE_CONFLICT","Resume acknowledgement trước suspension.");}
  boolean never=request.path("neverStarted").asBoolean();if(never&&(!Set.of("TERMINATE","STOP").contains(kind)||!c.body().path("serviceState").asString().equals("NOT_STARTED")||hasStarted(c.id())))throw ApiException.of("STATE_CONFLICT","Never-started proof mâu thuẫn lịch sử dịch vụ.");if(Set.of("TERMINATE","STOP").contains(kind)&&c.body().path("serviceState").asString().equals("NOT_STARTED")&&!never)throw ApiException.of("READINESS_BLOCKED","NOT_STARTED chưa là verified never-started proof.");if(kind.equals("TERMINATE")){var on=LocalDate.parse(r.body().path("effectOn").asString());if(on.isAfter(calendar.localDate(clock.instant()))||on.isBefore(LocalDate.parse(c.body().path("currentVersion").path("effectiveFrom").asString())))throw ApiException.of("STATE_CONFLICT","Termination effectOn ngoài authoritative current interval.");if(c.body().path("serviceState").asString().equals("NOT_STARTED")&&!never)throw ApiException.of("READINESS_BLOCKED","NOT_STARTED chưa là verified never-started proof.");}
  var proof=(ObjectNode)request.deepCopy();proof.put("revisionId",f.id().toString()).put("sourceHash",f.hash()).put("contractId",c.id().toString()).put("kind",kind).put("assessedBy",actor.id().toString()).put("recordedAt",now());proof.set("sourceContributors",json.value(excluded.stream().map(UUID::toString).toList()));proof.set("manifest",evidence.manifest(r,refs,actor,true));proof.set("beforeServiceState",c.body().path("serviceState"));String next=switch(kind){case "ACTIVATE","RESUME"->"RUNNING";case "SUSPEND"->"SUSPENDED";default->"STOPPED";};proof.put("afterServiceState",next);
  store.jdbc().update("insert into cg_control_confirmation(request_id,contract_id,kind,revision_id,body,body_hash,assessed_by,observed_at,recorded_at) values(?,?,?,?,?::jsonb,?,?,?,?)",r.id(),c.id(),kind,f.id(),json.stringify(proof),json.hash(proof),actor.id(),Timestamp.from(observed),Timestamp.from(Instant.parse(proof.path("recordedAt").asString())));var b=(ObjectNode)r.body().deepCopy();b.put("state","CONFIRMED");b.set("externalAcknowledgement",request.path("externalAcknowledgement"));b.set("observedAt",request.path("observedAt"));var updated=save(r,b,actor,"CONFIRM",request.path("reason").asString());if(kind.equals("TERMINATE")){changes.endApplicability(c,actor);notices.endApplicability(c.id(),actor);cancelOthers(c.id(),r.id(),actor);lifecycle.terminateLocked(c,r,observed,actor);}else{var cb=(ObjectNode)c.body().deepCopy();cb.put("serviceState",next);lifecycle.save(c,cb,actor,"SERVICE_"+kind,request.path("reason").asString());}return updated;
 }
 public Instant lastSuspension(UUID contract){return store.jdbc().query("select body::text from cg_control_confirmation where contract_id=? and kind='SUSPEND' order by recorded_at desc,request_id desc limit 1",(rs,n)->Instant.parse(json.parse(rs.getString(1)).path("externalAcknowledgement").path("observedAt").asString()),contract).stream().findFirst().orElseThrow(()->ApiException.of("READINESS_BLOCKED","Thiếu actual suspension source."));}
 private boolean hasStarted(UUID contract){return store.jdbc().queryForObject("select count(*) from cg_control_confirmation where contract_id=? and kind in ('ACTIVATE','RESUME')",Long.class,contract)>0L;}
 public void cancelOthers(UUID contract,UUID keep,Actor actor){var ids=store.jdbc().query("select id from cg_entity where entity_type='ControlRequest' and body->>'contractId'=? and id<>? and body->>'state' not in ('CONFIRMED','REJECTED','CANCELLED') order by id",(rs,n)->rs.getObject(1,UUID.class),contract.toString(),keep);for(var id:ids){var other=store.lock("ControlRequest",id);approval.getObject().cancelRound(other,actor);var b=(ObjectNode)other.body().deepCopy();b.put("state","CANCELLED");save(other,b,actor,"CANCEL","Confirmed termination ended applicability");}}
 public void event(EntityStore.Entity r,String kind,JsonNode body,Actor actor){store.jdbc().update("insert into cg_control_event(id,request_id,kind,body,body_hash,actor_id,recorded_at) values(?,?,?,?::jsonb,?,?,?)",UUID.randomUUID(),r.id(),kind,json.stringify(body),json.hash(body),actor==null?null:actor.id(),Timestamp.from(clock.instant()));}
 public JsonNode get(UUID id,Actor actor){var r=require(id,actor);lifecycle.maintain(id(r.body(),"contractId"),actor);return project(require(id,actor),actor);}
 public JsonNode list(Map<String,String> query,Actor actor){actor=users.actor(actor.id());actor.requireRole("MAKER","CHECKER","MANAGER","DATA_OFFICER","AUDITOR");var args=new ArrayList<Object>();String where="exists(select 1 from cg_entity c join cg_entity r on r.entity_type='Relationship' and r.id=(c.body->>'relationshipId')::uuid and r.branch_id=c.branch_id where c.entity_type='Contract' and c.id=(e.body->>'contractId')::uuid and c.branch_id=e.branch_id and "+customers.businessSqlScope(actor,"r")+")";if(!actor.hasAnyRole("CHECKER","MANAGER","DATA_OFFICER","AUDITOR"))args.add(actor.id().toString());var current=actor;return lists.page("ControlRequest",actor,query,false,where,args,b->project(new EntityStore.Entity("ControlRequest",id(b,"id"),id(b,"branchId"),b.path("version").asInt(),b),current));}
 public JsonNode project(EntityStore.Entity r,Actor actor){var b=(ObjectNode)r.body().deepCopy();var allowed=json.array();var blocked=json.array();for(String action:List.of("SUBMIT","CONFIRM","CANCEL")){boolean relevant=switch(action){case "SUBMIT"->b.path("state").asString().equals("DRAFT");case "CONFIRM"->Set.of("REQUESTED","APPROVED").contains(b.path("state").asString());default->Set.of("DRAFT","REQUESTED","IN_REVIEW","APPROVED").contains(b.path("state").asString());};if(!relevant)continue;try{authorize(r,action,actor);if(!action.equals("CANCEL")){sourceGuard(r);if(!action.equals("SUBMIT")){if(!r.body().hasNonNull("requesterId")&&!r.body().hasNonNull("roundId")&&store.jdbc().queryForObject("select count(*) from cg_control_revision where request_id=?",Long.class,r.id())==0L){evidence.manifest(r,evidence.ids(r.body().path("evidenceFileIds")),actor,false);var current=store.require("Contract",id(r.body(),"contractId"));evidence.manifest(r,List.of(id(current.body().path("currentVersion"),"artifactId")),actor,false);}else current(r,frozen(r),actor);}}allowed.add(action);}catch(ApiException e){if(actor.hasAnyRole("MAKER","CHECKER","MANAGER"))blocked.add(json.object().put("action",action).put("code",e.code()).put("reason",e.getMessage()));}}if(actor.hasRole("AUDITOR")&&!actor.hasAnyRole("MAKER","CHECKER","MANAGER","DATA_OFFICER")&&!actor.hasPermission("SENSITIVE_READ")){b.put("reason","[REDACTED]");if(b.hasNonNull("externalAcknowledgement"))((ObjectNode)b.path("externalAcknowledgement")).put("basis","[REDACTED]");}b.set("allowedActions",allowed);b.set("blockedActions",blocked);return b;}
}
